impl From<YYToken> for Qualifiers {
                fn from(token: YYToken) -> Qualifiers {
                    match token {
YYToken::type_qualifier(s) => s,
                    _ => panic!("wrong type"),
                    }
                }
            }
impl From<YYToken> for String {
                fn from(token: YYToken) -> String {
                    match token {
YYToken::IDENTIFIER(s)|YYToken::STRING_LITERAL(s) => s,
                    _ => panic!("wrong type"),
                    }
                }
            }
